    STreeNode n1 = { 0, 0, 0, 1 }, n2 = { 0, 0, 0, 2 }, n3 = { 0, 0, 0, 3 };
    n2._M_left = &n1; n2._M_right = &n3; n1._M_parent = &n2; n3._M_parent = &n2;
